using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioSelectionPaintInputValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static AnimationStudioWindow host;static MashBoxStudioViewport view;static StudioModelEditor editor;static int checks,step,modeIndex;static double next;static string report;static bool project=true;static List<(Vector2 point,int hit,Vector2 gui)> targets=new List<(Vector2,int,Vector2)>();static Vector2 nativeMouseOffset,lastGuiPointer,lastScreenConverted;static object markerBuffer;static int pickBuilds;static int[] painted;static Vector3[] source;static Transform[] transforms;
 static StudioModelEditor.ComponentMode[] modes={StudioModelEditor.ComponentMode.Face,StudioModelEditor.ComponentMode.Vertex,StudioModelEditor.ComponentMode.Edge};
 static object Get(object o,string n)=>o.GetType().GetField(n,F).GetValue(o);static void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);static object Call(object o,string n,params object[] a)=>o.GetType().GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);
 static void Check(bool ok,string message){if(!ok)throw new Exception(modes[Math.Min(modeIndex,2)]+" step "+step+": "+message);checks++;}
 public static void Run(){StudioPaintFeedbackValidation.Bounds();EditorApplication.delayCall+=Start;}
 static void Start(){report=Path.GetFullPath(Path.Combine(Application.dataPath,"../../paint-cursor-result.txt"));try{var doc=StudioModelDocument.CreateEmpty(StudioModelDocument.NewWorkspacePath("Paint Drag Input"));doc.AddPrimitive(PrimitiveType.Cube);host=ScriptableObject.CreateInstance<AnimationStudioWindow>();EditorApplication.delayCall-=(EditorApplication.CallbackFunction)Delegate.CreateDelegate(typeof(EditorApplication.CallbackFunction),host,"Restore");view=ScriptableObject.CreateInstance<MashBoxStudioViewport>();view.Studio=host;Set(host,"viewport",view);Set(host,"modelDocument",doc);Set(host,"modelingMode",true);view.position=new Rect(60,60,1500,900);view.Show();Call(host,"EnsureModelEditor");editor=(StudioModelEditor)Get(host,"modelEditor");Call(host,"BindStudioMode");editor.SelectObject(0);editor.SetToolbarComponentMode(modes[0]);source=editor.ActiveMesh.vertices;transforms=editor.Transforms.ToArray();view.LookAtDirect(Vector3.zero,Quaternion.Euler(25,35,0),2);view.orthographic=false;view.Focus();SceneView.duringSceneGui+=Project;next=EditorApplication.timeSinceStartup+1;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}}
 static void Project(SceneView scene){if(scene==view&&Event.current.type==EventType.Repaint){lastGuiPointer=Event.current.mousePosition;lastScreenConverted=view.CanvasMousePosition??Vector2.zero;}if(!project||scene!=view||Event.current.type!=EventType.Repaint)return;try{targets.Clear();var v=editor.ActiveMesh.vertices;var t=editor.Transforms[0];var candidates=new List<Vector3>();if(modes[modeIndex]==StudioModelEditor.ComponentMode.Vertex)candidates.AddRange(v);else if(modes[modeIndex]==StudioModelEditor.ComponentMode.Edge)foreach(var edge in (List<(int a,int b)>)Call(editor,"Edges"))candidates.Add((v[edge.a]+v[edge.b])*.5f);else foreach(var face in new StudioMeshCuts(editor.Document.nodes[0]).Faces)candidates.Add(face.Vertices.Aggregate(Vector3.zero,(p,i)=>p+v[i])/face.Vertices.Count);foreach(var local in candidates){var pixel=view.camera.WorldToScreenPoint(t.TransformPoint(local));var p=new Vector2(pixel.x,view.camera.pixelHeight-pixel.y)/EditorGUIUtility.pixelsPerPoint;var rootPoint=p+view.CanvasInputOrigin;if(!view.ModelCanvasRect.Contains(rootPoint)||targets.Any(h=>Vector2.Distance(h.point,rootPoint)<6))continue;int hit=editor.ReferencePaintHit(view,p);Check((int)Call(editor,"FindSelectionPaintComponent",view,p)==hit,"Cached pick differs from full scan");if(hit>=0&&!targets.Any(h=>h.hit==hit))targets.Add((rootPoint,hit,p));}project=false;}catch(Exception e){Finish(e.ToString());}}
 static void Key(bool down,KeyCode key,EventModifiers mods=EventModifiers.None){view.Focus();var input=new Event{type=down?EventType.KeyDown:EventType.KeyUp,keyCode=key,modifiers=mods};if(down){using(var evt=KeyDownEvent.GetPooled(input)){evt.target=view.rootVisualElement;view.rootVisualElement.SendEvent(evt);}}else{using(var evt=KeyUpEvent.GetPooled(input)){evt.target=view.rootVisualElement;view.rootVisualElement.SendEvent(evt);}}}
 static void Pointer(Vector2 p){using(var evt=PointerMoveEvent.GetPooled(new Event{type=EventType.MouseMove,mousePosition=p})){evt.target=view.rootVisualElement;view.rootVisualElement.SendEvent(evt);}}
 static void Mouse(EventType type,int target,EventModifiers mods=EventModifiers.None){view.Focus();view.SendEvent(new Event{type=type,button=0,mousePosition=targets[target].point+nativeMouseOffset,modifiers=mods,delta=Vector2.one});}
 static void Tick(){if(EditorApplication.timeSinceStartup<next||project)return;next=EditorApplication.timeSinceStartup+.25;try{switch(step++){
 case 0:Check(targets.Count>=2,"Need two visible native pick targets");view.SendEvent(new Event{type=EventType.MouseMove,mousePosition=targets[0].point});nativeMouseOffset=targets[0].gui-(view.CanvasMousePosition??Vector2.zero);view.SendEvent(new Event{type=EventType.MouseMove,mousePosition=targets[0].point+nativeMouseOffset});Check(Vector2.Distance(view.CanvasMousePosition??Vector2.zero,targets[0].gui)<.1f,"Native SendEvent calibration missed camera target");EditorGUIUtility.editingTextField=false;UnityEditor.Undo.ClearAll();StudioUndo.ClearForTests();editor.Components.Clear();Pointer(targets[0].point);Key(true,KeyCode.Tab);Check((bool)Get(editor,"selectionPaintArmed")&&Get(editor,"selectionPaintBefore")==null,"Tab must arm without beginning a stroke");Mouse(EventType.MouseMove,1);Check(editor.Components.Count==0,"Hover without left button painted selection");Call(editor,"FinishSelectionPaint",false);Check(!(bool)Get(editor,"selectionPaintArmed")&&view.SelectionPaintHoldActive,"Lost armed state also lost held-key ownership");Set(editor,"marquee",true);Mouse(EventType.MouseDown,0);break;
 case 1:Check(Get(editor,"selectionPaintBefore")!=null,"Left mouse down did not capture paint stroke; armed="+Get(editor,"selectionPaintArmed")+" hot="+GUIUtility.hotControl+" inside="+Get(view,"selectionPaintInputInside")+" focus="+(EditorWindow.focusedWindow?EditorWindow.focusedWindow.GetType().Name:"null"));Check(editor.Components.Contains(targets[0].hit),"Initial clicked component was not selected; expected="+targets[0].hit+" actual="+string.Join(",",editor.Components)+" pending="+Get(editor,"selectionPaintPending")+" pointer="+Get(editor,"selectionPaintPointer")+" target="+targets[0].point+" expectedGui="+targets[0].gui+" nativeGuiPointer="+lastGuiPointer+" screenConverted="+lastScreenConverted+" inputOrigin="+view.CanvasInputOrigin);Check(Vector2.Distance((Vector2)Get(editor,"selectionPaintPointer"),targets[0].gui)<.5f,"Paint cursor offset from projected GUI target: actual="+Get(editor,"selectionPaintPointer")+" expected="+targets[0].gui);Check((int)Get(editor,"hoveredComponent")==targets[0].hit&&(int)Get(editor,"drawnHover")==targets[0].hit,"Paint hover feedback is missing on selected target");markerBuffer=Get(editor,"markerPositions");pickBuilds=editor.PaintPickIndexBuilds;StudioPaintFeedbackValidation.QueuePixels(editor,view,modes[modeIndex].ToString());Mouse(EventType.MouseDrag,1);break;
 case 2:Check(editor.Components.Contains(targets[0].hit)&&editor.Components.Contains(targets[1].hit),"Dragging across components did not add selection");Check(!(bool)Get(editor,"marquee"),"Marquee captured paint drag");Check((int)Get(editor,"selectionPaintControl")!=0,"Paint drag has no dedicated input control");Check(editor.PaintPickIndexBuilds==pickBuilds,"Selection-only hit rebuilt paint index");if(modes[modeIndex]==StudioModelEditor.ComponentMode.Vertex)Check(ReferenceEquals(markerBuffer,Get(editor,"markerPositions")),"Selection paint recreated GPU position buffer");painted=editor.Components.ToArray();Mouse(EventType.MouseUp,1);break;
 case 3:Check(Get(editor,"selectionPaintBefore")==null&&(bool)Get(editor,"selectionPaintArmed"),"Mouse up must finish stroke and keep Tab armed; before="+(Get(editor,"selectionPaintBefore")!=null)+" armed="+Get(editor,"selectionPaintArmed")+" pending="+Get(editor,"selectionPaintPending")+" finish="+Get(editor,"selectionPaintFinishPending")+" focus="+(EditorWindow.focusedWindow?EditorWindow.focusedWindow.GetType().Name:"null"));Check(StudioUndo.RetainedActions==1,"Paint drag must be one undo action");Mouse(EventType.MouseDown,0);Mouse(EventType.MouseUp,0);break;
 case 4:Check((bool)Get(editor,"selectionPaintArmed")&&StudioUndo.RetainedActions==1,"Repeated click with Tab held added no-op undo or lost hold");Mouse(EventType.MouseMove,1);Check((int)Get(editor,"hoveredComponent")==targets[1].hit&&editor.Components.SetEquals(painted),"Armed hover failed or changed selection without a click");Set(editor,"pivot",true);Call(editor,"FinishSelectionPaint",false);Mouse(EventType.MouseDown,0);Mouse(EventType.MouseDrag,1);Mouse(EventType.MouseUp,1);Check(!(bool)Get(editor,"marquee")&&view.SelectionPaintHoldActive,"Invalid paint context fell through to marquee");Set(editor,"pivot",false);Key(false,KeyCode.Tab);Check(!(bool)Get(editor,"selectionPaintArmed")&&!view.SelectionPaintHoldActive,"Tab release did not disarm/release ownership");Pointer(targets[0].point);Key(true,KeyCode.Tab,EventModifiers.Control);Mouse(EventType.MouseMove,0,EventModifiers.Control);Check(editor.Components.SetEquals(painted),"Ctrl+Tab hover unpainted without clicking");Mouse(EventType.MouseDown,0,EventModifiers.Control);Mouse(EventType.MouseDrag,1,EventModifiers.Control);Mouse(EventType.MouseUp,1,EventModifiers.Control);break;
 case 5:Check(editor.Components.Count==0,"Ctrl+Tab left drag did not unpaint crossed components");Check(StudioUndo.RetainedActions==2,"Unpaint drag must be one undo action");Key(false,KeyCode.Tab);editor.PerformWorkspaceHistory(false);Check(editor.Components.SetEquals(painted),"Unpaint Undo lost source selection");Check(editor.Transforms.SequenceEqual(transforms)&&editor.ActiveMesh.vertices.SequenceEqual(source),"Paint changed geometry or rebuilt scene");Pointer(targets[0].point);Key(true,KeyCode.Tab,EventModifiers.Control);Mouse(EventType.MouseDown,0,EventModifiers.Control);break;
 case 6:Check(!editor.Components.Contains(targets[0].hit),"Cancel setup did not unpaint clicked component");Key(true,KeyCode.Escape);Check(editor.Components.SetEquals(painted)&&!(bool)Get(editor,"selectionPaintArmed")&&Get(editor,"selectionPaintBefore")==null,"Escape did not restore and release drag");Mouse(EventType.MouseUp,0);Check(!(bool)Get(editor,"marquee"),"Cancelled Tab hold allowed marquee");Key(false,KeyCode.Tab);Check(!view.SelectionPaintHoldActive,"Key up retained suppression");if(++modeIndex==modes.Length){Finish(null);break;}editor.SetToolbarComponentMode(modes[modeIndex]);targets.Clear();project=true;step=0;view.MarkDirty(MashBoxStudioViewport.DirtyState.All);break;
 }}catch(Exception e){Finish(e.ToString());}}
 static void Finish(string failure){if(failure==null)failure=StudioPaintFeedbackValidation.Failure;if(failure==null&&StudioPaintFeedbackValidation.Captures!=3)failure="Missing GPU hover captures";EditorApplication.update-=Tick;SceneView.duringSceneGui-=Project;File.WriteAllText(report,failure??("PASS "+checks+" native Tab+left-drag assertions across face/vertex/edge"));if(view)view.Close();if(host)Object.DestroyImmediate(host);EditorApplication.delayCall+=()=>EditorApplication.Exit(failure==null?0:1);}
}
